import type { NextConfig } from 'next';

const nextConfig: NextConfig = {
  reactStrictMode: true,
};

export default nextConfig;

{
  "compilerOptions": {
    "lib": ["dom", "dom.iterable", "esnext"],
    "allowJs": true,
    "skipLibCheck": true,
    "strict": true,
    "noEmit": true,
    "esModuleInterop": true,
    "module": "esnext",
    "moduleResolution": "bundler",
    "resolveJsonModule": true,
    "isolatedModules": true,
    "jsx": "preserve",
    "incremental": true,
    "plugins": [
      {
        "name": "next"
      }
    ],
    "paths": {
      "@/*": ["./*"]
    }
  },
  "include": ["next-env.d.ts", "**/*.ts", "**/*.tsx", ".next/types/**/*.ts"],
  "exclude": ["node_modules"]
}

/// <reference types="next" />
/// <reference types="next/image-types/global" />

// NOTE: This file should not be edited
// see https://nextjs.org/docs/basic-features/typescript for more information.

export type Book = {
  id: string;
  title: string;
  author: string;
  notes: string;
  finished: boolean;
  finishedAt?: string;
};

import { promises as fs } from 'fs';
import path from 'path';
import type { Book } from './types';

const DATA_DIR = path.join(process.cwd(), 'data');
const DATA_FILE = path.join(DATA_DIR, 'books.json');

async function ensureDataFile() {
  try {
    await fs.access(DATA_FILE);
  } catch {
    await fs.mkdir(DATA_DIR, { recursive: true });
    await fs.writeFile(DATA_FILE, JSON.stringify([], null, 2));
  }
}

export async function getBooks(): Promise<Book[]> {
  await ensureDataFile();
  const raw = await fs.readFile(DATA_FILE, 'utf-8');
  return JSON.parse(raw);
}

export async function getBook(id: string): Promise<Book | undefined> {
  const books = await getBooks();
  return books.find((b) => b.id === id);
}

export async function addBook(book: Omit<Book, 'id'>): Promise<Book> {
  const books = await getBooks();
  const newBook: Book = { ...book, id: crypto.randomUUID() };
  books.push(newBook);
  await fs.writeFile(DATA_FILE, JSON.stringify(books, null, 2));
  return newBook;
}

export async function finishBook(id: string): Promise<Book | undefined> {
  const books = await getBooks();
  const index = books.findIndex((b) => b.id === id);
  if (index === -1) return undefined;
  books[index] = {
    ...books[index],
    finished: true,
    finishedAt: new Date().toISOString(),
  };
  await fs.writeFile(DATA_FILE, JSON.stringify(books, null, 2));
  return books[index];
}

export async function updateBook(
  id: string,
  updates: Partial<Pick<Book, 'title' | 'author' | 'notes'>>
): Promise<Book | undefined> {
  const books = await getBooks();
  const index = books.findIndex((b) => b.id === id);
  if (index === -1) return undefined;
  books[index] = { ...books[index], ...updates };
  await fs.writeFile(DATA_FILE, JSON.stringify(books, null, 2));
  return books[index];
}

export async function deleteBook(id: string): Promise<boolean> {
  const books = await getBooks();
  const nextBooks = books.filter((b) => b.id !== id);
  if (nextBooks.length === books.length) return false;
  await fs.writeFile(DATA_FILE, JSON.stringify(nextBooks, null, 2));
  return true;
}

'use server';

import { revalidatePath } from 'next/cache';
import { redirect } from 'next/navigation';
import { addBook, finishBook, updateBook, deleteBook } from '@/lib/books';

export async function createBookAction(formData: FormData) {
  const title = String(formData.get('title') ?? '').trim();
  const author = String(formData.get('author') ?? '').trim();
  const notes = String(formData.get('notes') ?? '').trim();

  if (!title || !author) {
    throw new Error('Title and author are required');
  }

  const book = await addBook({ title, author, notes, finished: false });
  revalidatePath('/');
  redirect(`/book/${book.id}`);
}

export async function finishBookAction(id: string) {
  await finishBook(id);
  revalidatePath('/');
  revalidatePath(`/book/${id}`);
}

export async function updateBookAction(id: string, formData: FormData) {
  const title = String(formData.get('title') ?? '').trim();
  const author = String(formData.get('author') ?? '').trim();
  const notes = String(formData.get('notes') ?? '').trim();

  await updateBook(id, { title, author, notes });
  revalidatePath('/');
  revalidatePath(`/book/${id}`);
}

export async function deleteBookAction(id: string) {
  await deleteBook(id);
  revalidatePath('/');
  redirect('/');
}

* {
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  max-width: 680px;
  margin: 0 auto;
  padding: 2rem 1rem;
  line-height: 1.5;
  color: #222;
  background: #fafafa;
}

h1, h2, h3 {
  margin: 0 0 0.5rem;
}

a {
  color: #0366d6;
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

form {
  display: grid;
  gap: 0.75rem;
  margin: 1rem 0 1.5rem;
}

label {
  display: grid;
  gap: 0.25rem;
  font-weight: 500;
}

input, textarea {
  padding: 0.5rem;
  font: inherit;
  border: 1px solid #ccc;
  border-radius: 0.375rem;
}

button {
  justify-self: start;
  padding: 0.5rem 1rem;
  font: inherit;
  border: 1px solid #ccc;
  border-radius: 0.375rem;
  background: #fff;
  cursor: pointer;
}

button[type='submit'] {
  background: #222;
  color: #fff;
  border-color: #222;
}

button:hover {
  opacity: 0.9;
}

.book-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  gap: 0.75rem;
}

.book-list li {
  background: #fff;
  border: 1px solid #e2e2e2;
  border-radius: 0.5rem;
  padding: 1rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.book-list h3 {
  margin: 0 0 0.25rem;
}

.book-list p {
  margin: 0;
  color: #555;
}

section {
  margin-bottom: 2rem;
}

.empty {
  color: #666;
  font-style: italic;
}

.back {
  display: inline-block;
  margin-bottom: 1rem;
}

.actions {
  display: flex;
  gap: 0.5rem;
  align-items: center;
}

.badge {
  font-size: 0.75rem;
  padding: 0.125rem 0.5rem;
  border-radius: 9999px;
  background: #e2e2e2;
  color: #444;
}

.notes {
  white-space: pre-wrap;
  background: #fff;
  border: 1px solid #e2e2e2;
  border-radius: 0.5rem;
  padding: 1rem;
  min-height: 4rem;
}

import './globals.css';

export const metadata = {
  title: 'My Reading List',
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  );
}

import Link from 'next/link';
import { getBooks } from '@/lib/books';
import { finishBookAction, createBookAction } from './actions';

export default async function HomePage() {
  const books = await getBooks();
  const reading = books.filter((b) => !b.finished);
  const finished = books.filter((b) => b.finished);

  return (
    <main>
      <h1>My Reading List</h1>

      <section>
        <h2>Add a book</h2>
        <form action={createBookAction}>
          <label>
            Title
            <input name="title" required placeholder="Book title" />
          </label>
          <label>
            Author
            <input name="author" required placeholder="Author name" />
          </label>
          <label>
            Notes
            <textarea name="notes" rows={3} placeholder="Why are you reading this?" />
          </label>
          <button type="submit">Add book</button>
        </form>
      </section>

      <section>
        <h2>Currently reading</h2>
        {reading.length === 0 ? (
          <p className="empty">You are not reading any books yet.</p>
        ) : (
          <ul className="book-list">
            {reading.map((book) => (
              <li key={book.id}>
                <div>
                  <h3>
                    <Link href={`/book/${book.id}`}>{book.title}</Link>
                  </h3>
                  <p>by {book.author}</p>
                </div>
                <form action={finishBookAction.bind(null, book.id)}>
                  <button type="submit">Finish</button>
                </form>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h2>Finished</h2>
        {finished.length === 0 ? (
          <p className="empty">No finished books yet.</p>
        ) : (
          <ul className="book-list">
            {finished.map((book) => (
              <li key={book.id}>
                <div>
                  <h3>
                    <Link href={`/book/${book.id}`}>{book.title}</Link>
                  </h3>
                  <p>
                    by {book.author}
                    {book.finishedAt && (
                      <span className="badge">
                        {new Date(book.finishedAt).toLocaleDateString()}
                      </span>
                    )}
                  </p>
                </div>
                <span className="badge">Finished</span>
              </li>
            ))}
          </ul>
        )}
      </section>
    </main>
  );
}

import Link from 'next/link';
import { notFound } from 'next/navigation';
import { getBook } from '@/lib/books';
import { updateBookAction, deleteBookAction } from '../actions';

interface BookPageProps {
  params: Promise<{ id: string }>;
}

export default async function BookPage({ params }: BookPageProps) {
  const { id } = await params;
  const book = await getBook(id);

  if (!book) {
    notFound();
  }

  return (
    <main>
      <Link href="/" className="back">← Back to list</Link>

      <h1>{book.title}</h1>
      <p>by {book.author}</p>

      <section>
        <h2>Notes</h2>
        {book.notes ? (
          <div className="notes">{book.notes}</div>
        ) : (
          <p className="empty">No notes yet.</p>
        )}
      </section>

      <section>
        <h2>Edit</h2>
        <form action={updateBookAction.bind(null, book.id)}>
          <label>
            Title
            <input name="title" defaultValue={book.title} required />
          </label>
          <label>
            Author
            <input name="author" defaultValue={book.author} required />
          </label>
          <label>
            Notes
            <textarea name="notes" rows={5} defaultValue={book.notes} />
          </label>
          <div className="actions">
            <button type="submit">Save changes</button>
          </div>
        </form>
      </section>

      <section>
        <h2>Delete</h2>
        <form action={deleteBookAction.bind(null, book.id)}>
          <button type="submit">Delete book</button>
        </form>
      </section>
    </main>
  );
}

